/usr/bin/bash -lc "/runtime/node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { Session } from './src/session.js';

let calls = 0;
const offline = new Session({ queryFn: ({ signal }) => { calls++; return signal.aborted; } }, { online: false });
const departed = offline.subscribe('central', { networkMode: 'online' });
offline.unsubscribe(departed);
offline.online(true);
await Promise.resolve();
assert.equal(calls, 0, 'a departed offline observer must not start on reconnect');

const remounted = offline.subscribe('central', { networkMode: 'online' });
await Promise.resolve();
assert.equal(calls, 1, 'a later observer can resume the pending lookup');
assert.equal(offline.snapshot('central').status, 'success');
offline.unsubscribe(remounted);

let resolve;
const retained = new Session({ queryFn: () => new Promise(r => { resolve = r; }) });
const active = retained.subscribe('harbor');
retained.unsubscribe(active);
resolve('Harbor Stop');
await Promise.resolve();
assert.deepEqual(retained.snapshot('harbor'), { status: 'success', fetchStatus: 'idle', data: 'Harbor Stop' });

let raced = 0;
const race = new Session({ queryFn: () => { raced++; return 'unexpected'; } }, { online: false });
const h = race.subscribe('market');
race.online(true);
race.unsubscribe(h);
await Promise.resolve();
assert.equal(raced, 0, 'queued reconnect work must re-check observer presence');
console.log('targeted session assertions passed');
NODE
